[{"name": "read_note", "arguments": {"note_id": 18}}]function read_note(note_id) {
    // Simulate reading a user's saved note by its ID.
    const notes = {
        18: "Lumen 已签版许可上限为 250 名用户，审计日志保留 180 天。试用草案中的 500 人上限没有生效。",
        // ... other possible note IDs and their contents
    };

    return new Promise((resolve, reject) => {
        if (notes[note_id]) {
            resolve(notes[note_id]);
        } else {
            reject("Note not found.");
        }
    });
}

function extract_todos(note_id) {
    // Simulate extracting action items from a user's saved note.
    const notes = {
        18: "Lumen 已签版许可上限为 250 名用户，审计日志保留 180 天。试用草案中的 500 人上限没有生效。",
        // ... other possible note IDs and their contents
    };

    return new Promise((resolve, reject) => {
        if (notes[note_id]) {
            const todos = notes[note_id].match(/审计日志保留 (\d+) 天/);
            resolve(todos ? todos[1] : "No action items found.");
        } else {
            reject("Note not found.");
        }
    });
}

function search_notes(query) {
    // Simulate searching through all saved user notes for a specific query.
    const globalNotes = [
        { id: 18, content: "Lumen 已签版许可上限为 250 名用户，审计日志保留 180 天。试用草案中的 500 人上限没有生效。" },
        // ... other possible note IDs and their contents
    ];

    return new Promise((resolve) => {
        const foundNotes = globalNotes.filter(note => note.content.includes(query));
        resolve(foundNotes.map(note => note.id)); // Return only the ID of matched notes.
    });
}

async function getNoteContentOrActionItems(note_id, actionItemOnly=false) {
    try {
        let content;

        if (actionItemOnly) {
            const todos = await extract_todos(note_id);
            return { type: 'todo', text: todos };
        } else {
            content = await read_note(note_id);

            // If there are no action items requested, just the note's main contents.
            return { type: 'noteContent', text: content };
        }
    } catch (error) {
        console.error(error);
        throw new Error("Failed to retrieve or process the specified note.");
    }
}

async function handleRequest(query, onlyActionItems=false) {
    try {
        const results = await search_notes(query);

        if (!results.length || onlyActionItems && !onlyActionItems) { // If no notes found and not looking for action items.
            throw new Error("No relevant information was retrieved from the user's saved notes.");
        }

        let response;

        if (onlyActionItems) {
            const firstNoteId = results[0];
            response = await getNoteContentOrActionItems(firstNoteId, true);
        } else { // If looking for note content.
            const firstNoteId = results[0];  // Assuming we want the most relevant one; could be improved with better search logic or user input to select from multiple matches.
            response = await getNoteContentOrActionItems(firstNoteId);
        }

        return {
            type: 'response',
            data: { note_content_or_todos: response }
        };
    } catch (error) {
        console.error(error);
        throw new Error("An error occurred while processing the request.");
    }
}

// Example usage:
handleRequest('审计日志保留').then(response => {
    if (response.type === 'response') {
        const { note_content_or_todos: data } = response.data;

        // Determine whether we have a todo or just content.
        switch(data.type) {
            case 'todo':
                console.log(`Action Item(s): ${data.text}`);
                break;
            default:
                console.log(`Note Content: ${data.text}`);
                break;
        }
    }
});

